/**
 * Embeds db/migrations/*.sql into db/migrations.generated.ts.
 *
 * Serverless bundles do not reliably include files read with fs at runtime, so
 * the migration SQL is imported as a module. The generated file is committed;
 * `predev` and `prebuild` regenerate it so it can never lag behind.
 *
 * Plain Node (no tsx) so the build survives an install without devDependencies.
 */
import fs from "node:fs";
import path from "node:path";

const dir = path.join(process.cwd(), "db", "migrations");
const files = fs
  .readdirSync(dir)
  .filter((file) => file.endsWith(".sql"))
  .sort();

const entries = files.map((name) => {
  const sql = fs.readFileSync(path.join(dir, name), "utf8");
  return `  {\n    name: ${JSON.stringify(name)},\n    sql: ${JSON.stringify(sql)},\n  },`;
});

const out = `// AUTO-GENERATED by scripts/embed-migrations.mjs — do not edit by hand.
// Regenerate with: npm run db:embed
export type EmbeddedMigration = { name: string; sql: string };
export const MIGRATIONS: EmbeddedMigration[] = [
${entries.join("\n")}
];
`;

const target = path.join(process.cwd(), "db", "migrations.generated.ts");
fs.writeFileSync(target, out, "utf8");
console.log(`Embedded ${files.length} migration(s) into ${path.relative(process.cwd(), target)}.`);
